+  return llvm::TypeSwitch<Operation *, EffectsTy>(op)
+      .Case([](annotation::MarkOp markOp) -> EffectsTy {
+        if (markOp->hasAttr(CVPipeline::kInlinableQuantScaleAttr)) {
+          return {};
