+static constexpr const char *DEBUG_TYPE = "clone-cube-dep-in-if";
+static constexpr llvm::StringLiteral kSkippedKernels[1] = {""};
+#define DBGS() (llvm::dbgs() << '[' << DEBUG_TYPE << "] ")
+#define LDBG(...)                                                              \
+  LLVM_DEBUG({                                                                 \
+    DBGS();                                                                    \
+    llvm::dbgs() << __VA_ARGS__ << "\n";                                       \
